syntax:
enum Name: string {
    case CaseA = "a";
    case CaseB = "b";
}

example:
enum OrderStatus: string {
    case Pending = "pending";
    case Shipped = "shipped";
}

$s = OrderStatus::from("shipped");
echo $s->name;   // Shipped
echo $s->value;  // shipped

